// End of customizable code
use std::io::{self, Write};

#[derive(Debug, Clone, Copy)]
enum LeftDigit { U, W, Y(Exp) }

#[derive(Debug, Clone, Copy, PartialEq)]
enum RightComponent { W, X(Exp), XR(Exp) }

impl LeftDigit {
    fn num_heads_send(&self, n_recv: &BigUint) -> BigUint {
        match &self {
            Self::U => n_recv / 2u8,
            Self::W => (n_recv + 1u8) / 2u8,
            Self::Y(_) => n_recv.clone(),
        }
    }

    fn max_heads_recv(&self, max_n_send: &BigUint) -> BigUint {
        match &self {
            Self::U => max_n_send * 2u8 + 1u8,
            Self::W => max_n_send * 2u8,
            Self::Y(_) => max_n_send.clone(),
        }
    }

    fn receive_heads(&mut self, n_heads: &BigUint) -> BigUint {
        match &self {
            Self::U => {
                let mut out = n_heads/2u8 * 11u8;
                if (n_heads % 2u8).to_u8().unwrap() == 1 {
                    out += 3u8;
                    *self = Self::W;
                }
                out
            },
            Self::W => {
                let mut out = n_heads/2u8 * 11u8;
                if (n_heads % 2u8).to_u8().unwrap() == 1 {
                    out += 8u8;
                    *self = Self::U;
                }
                out
            },
            Self::Y(n) => n_heads * n * 10u8,
        }
    }

    fn receive_heads_no_step_calc(&mut self, n_heads: &BigUint) {
        match &self {
            Self::U => {
                if (n_heads % 2u8).to_u8().unwrap() == 1 {
                    *self = Self::W;
                }
            },
            Self::W => {
                if (n_heads % 2u8).to_u8().unwrap() == 1 {
                    *self = Self::U;
                }
            },
            Self::Y(_) => (),
        }
    }

    fn to_block_symbol(&self) -> BlockSymbol {
        use BlockSymbol as B;
        match &self {
            Self::U => B::U,
            Self::W => B::W,
            Self::Y(n) => B::Run(RunSymbolType::Y, *n),
        }
    }

    fn try_from_block_symbol(s: &BlockSymbol) -> Option<LeftDigit> {
        use BlockSymbol as B;
        match s {
            B::U => Some(Self::U),
            B::W => Some(Self::W),
            B::Run(RunSymbolType::Y, n) => Some(Self::Y(*n)),
            _ => None,
        }
    }
}

impl RightComponent {
    fn do_strides(&mut self, n_strides: BigUint) -> Result<BigUint, SimError> {
        match self {
            Self::W => {
                Ok(n_strides * 11u8)
            }
            Self::X(n) => {
                Ok(n_strides * *n * 10u8)
            }
            Self::XR(n) => {
                let nadd: Exp = (&n_strides).try_into()
                    .or_else(|_| Err(SimError::Overflow))?;

                let s0 = BigUint::from(*n) * 10u8;
                let s1 = &n_strides * 5u8;
                let out = n_strides * (s0 + s1 - 4u8);

                *n += nadd;
                Ok(out)
            }
        }
    }

    fn do_strides_no_step_calc(&mut self, n_strides: BigUint) -> Result<(), SimError> {
        match self {
            Self::XR(n) => {
                let nadd: Exp = (&n_strides).try_into()
                    .or_else(|_| Err(SimError::Overflow))?;
                *n += nadd;
            }
            _ => (),
        }
        Ok(())
    }
}

impl BlockSimulator {
    pub fn new(do_counter_accel: bool, calculate_accel_steps: bool) -> Self {
        use BlockSymbol::*;
        use RunSymbolType::*;
        Self {
            left_tape: vec![L],
            right_tape: vec![R, Run(X, 2)],
            state: HigherState::Left,
            base_steps: BigUint::from(11u8),
            self_steps: 0,
            do_dividing_shift_steps: true,
            do_counter_accel, calculate_accel_steps
        }
    }

    pub fn new_with_tape(left_tape: Vec<BlockSymbol>, state: HigherState, right_tape: Vec<BlockSymbol>, do_counter_accel: bool, calculate_accel_steps: bool) -> Self {
        Self {
            left_tape, right_tape, state,
            base_steps: BigUint::ZERO,
            self_steps: 0,
            do_dividing_shift_steps: true,
            do_counter_accel, calculate_accel_steps
        }
    }

    fn max_before_left_counter_overflow(&self) -> BigUint {
        let mut digits: Vec<LeftDigit> = Vec::new();
        for s in self.left_tape.iter().rev() {
            if let Some(d) = LeftDigit::try_from_block_symbol(s) {
                digits.push(d);
            } else {
                break;
            }
        }
        let mut n = BigUint::ZERO;
        for d in digits.iter().rev() {
            n = d.max_heads_recv(&n);
        }
        n
    }

    fn increase_left_counter(&mut self, n0: &BigUint) -> BigUint {
        let mut steps = BigUint::ZERO;
        let mut n = n0.clone();
        let mut digits: Vec<LeftDigit> = Vec::new();
        while n > BigUint::ZERO {
            let mut d = LeftDigit::try_from_block_symbol(&self.left_tape.pop().unwrap()).unwrap();
            let n_new = d.num_heads_send(&n);
            if self.calculate_accel_steps {
                steps += d.receive_heads(&n);
            } else {
                d.receive_heads_no_step_calc(&n);
            }
            digits.push(d);
            n = n_new;
        }

        for d in digits.iter().rev() {
            self.left_tape.push(d.to_block_symbol());
        }

        steps
    }

    fn right_strides(&mut self, n_strides0: &BigUint) -> Result<BigUint, SimError> {
        let mut components: Vec<RightComponent> = Vec::new();
        let mut idx = self.right_tape.len();
        let mut n_strides = n_strides0.clone();
        let mut stride_vec: Vec<BigUint> = Vec::new();

        let mut done = false;
        while !done {
            use BlockSymbol::*;
            use RunSymbolType::*;

            let comp = match self.right_tape[..idx] {
                [R] => {
                    done = true;
                    RightComponent::XR(0)
                }
                [R, Run(X, n)] => {
                    done = true;
                    RightComponent::XR(n)
                }
                [.., Run(X, n)] => {
                    idx -= 1;
                    RightComponent::X(n)
                }
                [.., W] => {
                    idx -= 1;
                    RightComponent::W
                }
                _ => unreachable!("unexpected symbol reached while doing right stride {:?}", self.right_tape),
            };
            stride_vec.push(n_strides.clone());
            if comp == RightComponent::W {
                n_strides *= 2u8;
            }
            components.push(comp);
        }

        let mut n_steps = BigUint::ZERO;
        for (t, comp) in stride_vec.into_iter().zip(components.iter_mut()) {
            if self.calculate_accel_steps {
                n_steps += comp.do_strides(t)?;
            } else {
                comp.do_strides_no_step_calc(t)?;
            }
        }

        self.right_tape.clear();
        for comp in components.iter().rev() {
            use BlockSymbol as B;
            use RunSymbolType::*;
            match comp {
                RightComponent::XR(n) => {
                    self.right_tape.push(B::R);
                    if *n > 0 {
                        self.right_tape.push(B::Run(X, *n));
                    }
                },
                RightComponent::X(n) => add_or_merge_run(&mut self.right_tape, X, *n),
                RightComponent::W => self.right_tape.push(B::W),
            }
        }        
        
        Ok(n_steps)
    }

    fn try_counter_accel(&mut self) -> Result<Option<BigUint>, SimError> {
        use BlockSymbol as B;

        if !matches!(self.left_tape.last(), Some(B::W | B::U)) ||
            !matches!(self.state, HigherState::Left | HigherState::Right) ||
            self.right_tape.iter().any(|s| !matches!(s, B::W | B::R | B::Run(RunSymbolType::X, _))) {
            return Ok(None);
        }

        let n_incr_left = self.max_before_left_counter_overflow();
        let n_incr_right = if self.state == HigherState::Left {
            n_incr_left.clone()
        } else {
            self.state = HigherState::Left;
            &n_incr_left + 1u8
        };

        if n_incr_right == BigUint::ZERO {
            return Ok(None);
        }

        let mut steps = self.right_strides(&n_incr_right)?;
        if n_incr_left > BigUint::ZERO {
            steps += self.increase_left_counter(&n_incr_left);
        }

        Ok(Some(steps))
    }

    fn try_dividing_shift_rule(&mut self) -> Option<BigUint> {
        use HigherState::*;
        use BlockSymbol::*;
        use RunSymbolType::*;
        let n_steps = match (
            &self.state,
            self.left_tape.as_slice(),
            self.right_tape.as_slice(),
        ) {
            // f> X X -> G f>
            (RightFill, _, [.., Run(X, n0 @ 2u128..)]) => {
                let n = n0 / 2;
                decrease_run_by(&mut self.right_tape, X, n * 2u128);
                add_or_merge_run(&mut self.left_tape, G, n);
                BigUint::from(n) * 10u8
            }
            // U > GR GR GR -> H U >
            (Right, [.., U], [.., Run(GR, n0 @ 3u128..)]) => {
                let n = n0 / 3;
                self.left_tape.pop();
                decrease_run_by(&mut self.right_tape, GR, n * 3u128);
                add_or_merge_run(&mut self.left_tape, H, n);
                self.left_tape.push(U);
                BigUint::from(n) * 40u8
            }
            // U o> HR HR HR -> J U o>
            (RightOdd, [.., U], [.., Run(HR, n0 @ 3u128..)]) => {
                let n = n0 / 3;
                self.left_tape.pop();
                decrease_run_by(&mut self.right_tape, HR, n * 3u128);
                add_or_merge_run(&mut self.left_tape, J, n);
                self.left_tape.push(U);
                BigUint::from(n) * 698u16
            }
            // the following are not dividing shift rules but just want to avoid overflow...
            // G < -> < GR
            (Left, [.., Run(G, exp)], _) => {
                let n = *exp;
                self.left_tape.pop();
                add_or_merge_run(&mut self.right_tape, GR, n);
                BigUint::from(n) * 10u8
            }
            // H < -> < HR
            (Left, [.., Run(H, exp)], _) => {
                let n = *exp;
                self.left_tape.pop();
                add_or_merge_run(&mut self.right_tape, HR, n);
                BigUint::from(n) * 30u8
            }
            _ => return None,
        };
        Some(n_steps)
    }

    pub fn step(&mut self) -> Result<(), SimError> {
        if self.do_counter_accel && let Some(new_base_steps) = self.try_counter_accel()? {
            self.base_steps += new_base_steps;
            self.self_steps += 1;
            return Ok(());
        }

        if self.do_dividing_shift_steps && let Some(new_base_steps) = self.try_dividing_shift_rule() {
            self.base_steps += new_base_steps;
            self.self_steps += 1;
            return Ok(());
        }

        let new_base_steps = self.basic_step()?;
        self.base_steps += new_base_steps;
        self.self_steps += 1;
        Ok(())
    }

    pub fn in_counter_bouncer_mode(&self) -> bool {
        use BlockSymbol::*;
        use RunSymbolType::*;

        matches!(self.state, HigherState::Left | HigherState::Right)
        && self.left_tape.iter().all(|s| matches!(s, L1 | U | W | Run(J | Y, _)))
        && self.right_tape.iter().all(|s| matches!(s, W | Run(X, _) | R))
    }

    pub fn in_halting_configuration(&self) -> bool {
        use HigherState::*;
        use BlockSymbol::*;
        use RunSymbolType::*;

        matches!(
            (
                &self.state,
                self.left_tape.as_slice(),
                self.right_tape.as_slice(),
            ),
            (RightFill, _, [R2]) |
            (RightFill, _, [.., YR]) |
            (RightOdd, _, [R2, Q, P])
        )
    }
}

fn compare_accel_sim(n_steps: usize) {
    let mut sim = BlockSimulator::new(false, true);
    let mut sim_accel = BlockSimulator::new(true, true);

    for _ in 0..=n_steps {
        while sim.base_steps < sim_accel.base_steps {
            sim.step().unwrap();
        }
        println!("{sim_accel:>width$}", width=(sim.self_steps.checked_ilog10().unwrap_or(0) + 1) as usize);
        println!("{sim}");
        sim_accel.step().unwrap();
    }
}

fn compare_accel_sim2(n_steps: usize) {
    let mut sim1 = BlockSimulator::new(true, true);
    let mut sim2 = BlockSimulator::new(true, false);

    for _ in 0..=n_steps {
        assert!(sim1.left_tape == sim2.left_tape);
        assert!(sim1.right_tape == sim2.right_tape);
        assert!(sim1.state == sim2.state);

        sim1.step().unwrap();
        sim2.step().unwrap();
    }

    println!("{sim1}");
    println!("{sim2}");
}

fn compare_dividing_shift_sim(n_steps: usize) {
    let mut sim = BlockSimulator::new(true, true);
    sim.do_dividing_shift_steps = false;
    let mut sim_accel = BlockSimulator::new(true, true);

    for _ in 0..=n_steps {
        while sim.base_steps < sim_accel.base_steps {
            sim.step().unwrap();
        }
        println!("{sim_accel:>width$}", width=(sim.self_steps.checked_ilog10().unwrap_or(0) + 1) as usize);
        println!("{sim}");
        sim_accel.step().unwrap();
    }
}

